/// <summary>
///     The <c>AVABPJobsContract</c> class is the data contract class for <c>BP-Jobs</c>
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(AVABPJobsUIBuilder)),
    SysOperationGroupAttribute('BuildingProject',       literalStr("@SYP4910021"),                  '2'), // , FormArrangeMethod::Vertical),
    SysOperationGroupAttribute('Status',                literalStr("@SYS80127"),                    '3'),
    SysOperationGroupAttribute('PotentialSalesVolume',  literalStr("@NDX:NXAPotentialSalesVolume"), '4'),
    SysOperationGroupAttribute('Responsibilities',      literalStr("@NDX:NXAResponsibilities"),     '5'),
    SysOperationGroupAttribute('Activities',            literalStr("@SYS80847"),                    '6')
]
class AVABPJobsContract implements  SysOperationValidatable,
                                    SysOperationInitializable
{
    Args                        args;
    KCS_KBVBuildingProjectID    kCS_KBVBuildingProjectID;
    KBVPeriodicUpdate           kBVPeriodicUpdate;
    KBVPeriodicUpdateGLB        kBVPeriodicUpdateGLB;
    KBVUpdatePotSalesVol        kBVUpdatePotSalesVol;
    KBVUpdatePotSalesVolGLB     kBVUpdatePotSalesVolGLB;
    KBVSetResponsibilities      kBVSetResponsibilities;
    KBVActivitySendList         kBVActivitySendList;
    KCS_PrintMasterDataList     kCS_PrintMasterDataList;
    container                   processingInterval;
    boolean                     processSingleBatchTask;
    boolean                     runFromRico;


}

