public boolean validate()
{
    boolean retVal;

    retVal = true;

    return retVal;
}

/// <summary>
///    AVA <c>initialize</c> method.
/// </summary>
public void initialize()
{
    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    kcs_KBVBuildingProjectID = '';

    if (args && args.record())
    {
        locCommon = args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;

            kcs_KBVBuildingProjectID =  locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        }

    }

    kBVPeriodicUpdate       = true;
    kBVPeriodicUpdateGLB    = false;
    kBVUpdatePotSalesVol    = true;
    kBVUpdatePotSalesVolGLB = false;
    kBVSetResponsibilities  = true;
    kBVActivitySendList     = false;
    kCS_PrintMasterDataList = false;

}

